// Whitelist actions Telegram exposables a l'agent. chat force a 'caverne'.
const inp = $json || {};
const ALLOWED = {
  image:   ['prompt'],
  'send-file': ['path','caption'],
  history: ['limit'],
  read:    ['message_id'],
  search:  ['query','limit'],
  chatinfo:[],
  members: [], admins: [], stats: [], topics: [],
  poll:    ['question','options'],
};
const act = String(inp.action||'').toLowerCase().trim();
if (!ALLOWED[act]) return [{ json: { ok:false, error:"action refusee: "+act+" (permises: "+Object.keys(ALLOWED).join(', ')+")" } }];
const body = { action: act, chat: 'caverne' };
for (const k of ALLOWED[act]) if (inp[k] !== undefined && inp[k] !== null && inp[k] !== '') body[k] = inp[k];
if (body.message_id !== undefined) { body.messageId = Number(body.message_id)||0; delete body.message_id; }
if (act==='poll' && !Array.isArray(body.options)) body.options = String(body.options||'').split('|').map(s=>s.trim()).filter(Boolean);

body.asUser = false;
return [{ json: { ok:true, body } }];

